			// value found, but too old - re-run it under the same id
			[drop[r`id];
			 add[func;r`id;`rerun]]]];
		// it's not in the cache, so add it
		add[func;getid[];`add]]}

choleski:{
 n:count A:x+0.0;
 if[1>=n;:sqrt A];
 p:ceiling n%2;
 X:p#'p#A;
 Y:p _'p#A;
 Z:p _'p _A;
 T:(flip Y) mmu inv X;
 L0:n #' (choleski X) ,\: (n-1)#0.0;
 L1:choleski Z-T mmu Y;
 L0,(T mmu p#'L0),'L1}

